// These SVG glyphs are generated by Rustplotlib's native LaTeX mathpazo path.
export function mathAsset(label=''){
 const s=label.toLowerCase();let key;
 if(s.startsWith('raw ne'))key='raw-ne';
 else if(s.includes('ne proxy')||s.includes('uncalibrated ne'))key='ne-proxy';
 else if(s.startsWith('ne ')||s.startsWith('electron density'))key='ne';
 else if(s.startsWith('ti ')||s.startsWith('ion temperature'))key='ti';
 else if(s.startsWith('te ')||s.startsWith('electron temperature'))key='te';
 else if(s.startsWith('vi ')||s.startsWith('velocity')||s.startsWith('spectral velocity'))key='vi';
 else if(s.startsWith('tsys'))key='tsys';
 else if(s.startsWith('ptx'))key='ptx';
 return key?`vendor/math/${key}.svg?v=2`:null;
}
export function mathLabel(plot,key,asset,label,x,y,rotate=false){
 plot.mathLabels??={};let img=plot.mathLabels[key];
 if(!asset){if(img)img.hidden=true;return;}
 if(!img){img=document.createElement('img');img.className='scientific-math-label';(plot.host||plot.box).append(img);plot.mathLabels[key]=img;}
 img.hidden=false;img.src=asset;img.alt=label;Object.assign(img.style,{left:x+'px',top:y+'px',transform:`translate(-50%,-50%)${rotate?' rotate(-90deg)':''}`});
}
